import http from "k6/http";
import { check } from "k6";

export const options = {
  vus: 20,
  duration: "2m",
  thresholds: {
    http_req_failed: ["rate<0.01"],
    http_req_duration: ["p(95)<400"],
  },
};

export default function () {
  const res = http.get(`${__ENV.BASE_URL}/v1/orders/${__ENV.ORDER_ID}`, {
    headers: { Authorization: `Bearer ${__ENV.TOKEN}` },
  });
  check(res, { "status is 200": (r) => r.status === 200 });
}

// Every test reuses one seeded order and one seeded user.
const ORDER_ID = "ord_seed_001";

test("cancel an order", async () => {
  const res = await api.post(`/v1/orders/${ORDER_ID}/cancellation`);
  assert.equal(res.status, 200);
});

test("read an order", async () => {
  const res = await api.get(`/v1/orders/${ORDER_ID}`);
  assert.equal(res.body.status, "pending"); // fails whenever "cancel" ran first
});

// Each test creates what it needs, tagged with the run ID.
const runId = process.env.GITHUB_RUN_ID ?? Date.now().toString(36);

test("cancel an order", async () => {
  const order = await createOrder({ key: `${runId}-cancel` });
  const res = await api.post(`/v1/orders/${order.id}/cancellation`);
  assert.equal(res.status, 200);
});

test("read an order", async () => {
  const order = await createOrder({ key: `${runId}-read` });
  const res = await api.get(`/v1/orders/${order.id}`);
  assert.equal(res.body.status, "pending");
});

import test from "node:test";
import assert from "node:assert/strict";

const BASE = process.env.BASE_URL;
const runId = Date.now().toString(36);

async function createOrder(token, suffix) {
  const res = await fetch(`${BASE}/v1/orders`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
      "Idempotency-Key": `test-${runId}-${suffix}`,
    },
    body: JSON.stringify({ sku: "SKU-TEST-1", quantity: 1 }),
  });
  assert.equal(res.status, 201);
  return res.json();
}

test("user B cannot read user A's order", async () => {
  const order = await createOrder(process.env.TOKEN_A, "bola");
  const res = await fetch(`${BASE}/v1/orders/${order.id}`, {
    headers: { Authorization: `Bearer ${process.env.TOKEN_B}` },
  });
  assert.ok([403, 404].includes(res.status), `expected 403 or 404, got ${res.status}`);
});

test("a request with no token gets 401 and a Bearer challenge", async () => {
  const res = await fetch(`${BASE}/v1/orders/ord_does_not_matter`);
  assert.equal(res.status, 401);
  assert.match(res.headers.get("www-authenticate") ?? "", /^Bearer/);
});
